/* File: style.css */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
    color: #f8fafc;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 20px;
}

.app-container {
    background: rgba(30, 41, 59, 0.7);
    backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    width: 100%;
    max-width: 480px;
    border-radius: 16px;
    padding: 30px;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
}

header {
    margin-bottom: 24px;
}

header h1 {
    font-size: 1.8rem;
    font-weight: 700;
    color: #38bdf8;
    display: flex;
    align-items: center;
    gap: 10px;
}

header p {
    color: #94a3b8;
    font-size: 0.9rem;
    margin-top: 4px;
}

#todo-form {
    margin-bottom: 20px;
}

.input-group {
    display: flex;
    gap: 10px;
}

#todo-input {
    flex: 1;
    padding: 14px 18px;
    border-radius: 10px;
    border: 1px solid #334155;
    background: #0f172a;
    color: #f8fafc;
    font-size: 1rem;
    outline: none;
    transition: all 0.3s ease;
}

#todo-input:focus {
    border-color: #38bdf8;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
}

#add-btn {
    padding: 14px 20px;
    background: #38bdf8;
    color: #0f172a;
    border: none;
    border-radius: 10px;
    font-size: 1.1rem;
    font-weight: bold;
    cursor: pointer;
    transition: background 0.2s ease, transform 0.1s ease;
}

#add-btn:hover {
    background: #7dd3fc;
}

#add-btn:active {
    transform: scale(0.95);
}

.filter-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    gap: 10px;
    flex-wrap: wrap;
}

.filters {
    display: flex;
    gap: 6px;
    background: #0f172a;
    padding: 4px;
    border-radius: 8px;
}

.filter-btn {
    background: transparent;
    border: none;
    color: #94a3b8;
    padding: 6px 12px;
    font-size: 0.85rem;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.filter-btn.active, .filter-btn:hover {
    background: #334155;
    color: #f8fafc;
}

.clear-btn {
    background: transparent;
    border: none;
    color: #ef4444;
    font-size: 0.85rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

.clear-btn:hover {
    opacity: 0.8;
    text-decoration: underline;
}

.todo-list {
    list-style: none;
    max-height: 320px;
    overflow-y: auto;
    margin-bottom: 20px;
}

.todo-list::-webkit-scrollbar {
    width: 6px;
}

.todo-list::-webkit-scrollbar-thumb {
    background: #334155;
    border-radius: 3px;
}

.todo-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #0f172a;
    padding: 12px 16px;
    border-radius: 10px;
    margin-bottom: 10px;
    border: 1px solid #1e293b;
    transition: all 0.2s ease;
}

.todo-item:hover {
    border-color: #334155;
}

.todo-item.completed .todo-text {
    text-decoration: line-through;
    color: #64748b;
}

.todo-content {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    overflow: hidden;
}

.checkbox {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    border: 2px solid #64748b;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.todo-item.completed .checkbox {
    background: #10b981;
    border-color: #10b981;
}

.checkbox i {
    color: #0f172a;
    font-size: 0.75rem;
    display: none;
}

.todo-item.completed .checkbox i {
    display: block;
}

.todo-text {
    word-break: break-all;
    font-size: 0.95rem;
}

.delete-btn {
    background: transparent;
    border: none;
    color: #64748b;
    cursor: pointer;
    font-size: 1rem;
    padding: 4px;
    transition: color 0.2s ease;
}

.delete-btn:hover {
    color: #ef4444;
}

.stats-footer {
    font-size: 0.85rem;
    color: #64748b;
    border-top: 1px solid #334155;
    padding-top: 16px;
    text-align: right;
}

.empty-message {
    text-align: center;
    color: #64748b;
    padding: 20px 0;
    font-style: italic;
}
